CREATE OR REPLACE PROCEDURE ECAMS.UPDATE_1000STEP
(
 ACPTNO       IN   Varchar2,
 PRGSTEP      IN   NUMBER)
 IS
  SYSSTEP    NUMBER;
BEGIN
    SELECT nvl(cr_sysstep,0)
    into SYSSTEP
    from cmr1000
    where cr_acptno=ACPTNO;

    if PRGSTEP > SYSSTEP then
        UPDATE CMR1000
        SET cr_sysstep = PRGSTEP+1
        WHERE CR_ACPTNO = ACPTNO;
    end if;

End UPDATE_1000STEP;